.measurement-list > div span:last-child { text-align: right; }
.restore-warning { margin: 16px 0; padding: 12px; border: 1px solid var(--color-border-warning); border-radius: 12.5px; background: var(--color-background-warning); color: var(--color-status-warning); font-size: 12px; line-height: 18px; }
.field-label input:focus, .field-label textarea:focus, .field-label select:focus, .search input:focus { border-color: var(--color-accent); outline: none; box-shadow: 0 0 0 2px color-mix(in srgb,var(--color-accent) 12%,transparent); }
.button { transition: transform .15s var(--ease-out), color .15s var(--ease-out), background-color .15s var(--ease-out), border-color .15s var(--ease-out); }
.button:active:not(:disabled) { transform: translateY(1px); }
.text-button { padding: 0; border: 0; background: none; color: var(--color-text-accent); font-size: 12px; line-height: 18px; }
.text-button:hover:not(:disabled) { color: var(--color-text); text-decoration: underline; text-underline-offset: 3px; }
.more { display: block; margin: 16px auto; }
.refresh-button { width: 30px; height: 30px; }
.loading-spinner { display: inline-block; width: 15px; height: 15px; flex: none; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: control-spin .8s linear infinite; }
