/* Application shell, navigation and workspace sidebar. */
.app-shell { display: grid; grid-template-columns: 340px minmax(0,1fr); grid-template-rows: 36px minmax(0,1fr); height: 100dvh; overflow: hidden; background: var(--color-shell-background); transition: grid-template-columns .15s var(--ease-out); }
