.markdown h1, .markdown h2, .markdown h3 { margin: 24px 0 12px; line-height: 1.4; font-weight: 500; }
.markdown h1 { font-size: 24px; }
.markdown h2 { font-size: 20px; }
.markdown h3 { font-size: 18px; }
.markdown ul, .markdown ol { padding-left: 24px; }
.markdown blockquote { margin: 12px 0; padding-left: 12px; border-left: 2px solid var(--color-border); color: var(--muted); }
.markdown a, .markdown-link { color: var(--color-text-accent); text-decoration: underline; text-underline-offset: 2px; }
.markdown-link { padding: 0; border: 0; background: none; font: inherit; }
.markdown code { padding: 2px 4px; border-radius: 4px; background: var(--color-background-secondary-ghost-hover); font-size: .9em; }
.markdown table { display: block; overflow: auto; border-collapse: collapse; font-size: 13px; }
.markdown th, .markdown td { padding: 6px 8px; border: 1px solid var(--color-border-subtle); }
.code-block { margin: 12px 0; overflow: hidden; border: 1px solid var(--color-border-subtle); border-radius: 12.5px; background: var(--app-color-background-surface-under); }
.code-toolbar { display: flex; align-items: center; justify-content: space-between; padding: 6px 12px; border-bottom: 1px solid var(--color-border-subtle); color: var(--muted); font-size: 11px; line-height: 16px; }
.code-toolbar button { padding: 0; border: 0; background: none; color: var(--muted); font-size: 11px; opacity: 0; transition: opacity .15s var(--ease-out); }
.code-block:hover .code-toolbar button, .code-block:focus-within .code-toolbar button { opacity: 1; }
.code-block pre { margin: 0; max-height: 420px; overflow: auto; padding: 12px; white-space: pre; background: none; font-size: 12.5px; line-height: 1.6; }
.code-block pre code { padding: 0; background: none; font: inherit; }
@media (max-width: 760px) {
.timeline { padding-inline: 24px; }
.empty-conversation h2 { font-size: 24px; }
.event-detail dl > div { flex-wrap: wrap; }
.approval-scope { flex-wrap: wrap; gap: 4px; }
}
@media (hover: none) {
.message .message-meta, .message-actions, .command-card .copy-btn, .code-toolbar button { opacity: 1; } }
.conversation-files-toggle { display: grid; place-items: center; width: 32px; height: 32px; padding: 0; border: 0; border-radius: 7.5px; background: none; color: var(--muted); }
.conversation-files-toggle:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.conversation-changes-overview { display: flex; align-items: center; justify-content: space-between; gap: 16px; width: calc(100% - 12px); min-height: 40px; margin: 6px; padding: 8px; border: 0; border-bottom: 1px solid var(--color-border-subtle); border-radius: 7.5px 7.5px 0 0; background: none; text-align: left; font-size: 13px; }
.conversation-changes-overview:hover { background: var(--color-background-secondary-ghost-hover); }
.conversation-changes-overview > span:last-child { display: inline-flex; align-items: center; gap: 4px; color: var(--muted); font-size: 12px; }
.event-detail { font-size: 14px; line-height: 21px; }
.event-file-open { display: grid; place-items: center; flex: none; width: 21px; height: 21px; padding: 0; border: 0; border-radius: 5px; background: none; color: inherit; opacity: 0; transition: opacity .15s var(--ease-out); }
.event-line > summary:hover .event-file-open, .event-line:focus-within .event-file-open { opacity: 1; }
.event-file-open:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.activity-file-row { display: flex; align-items: center; gap: 8px; width: 100%; min-width: 0; min-height: 36px; padding: 6px 8px; border: 0; border-radius: 7.5px; background: none; color: var(--muted); text-align: left; font-size: 14px; line-height: 21px; }
.activity-file-row > svg { flex: none; width: 16px; height: 16px; }
.activity-file-row:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.activity-file-row:disabled { opacity: 1; cursor: default; }
.activity-file-copy { display: flex; min-width: 0; flex: 1; }
.activity-file-directory, .activity-file-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.activity-file-directory { flex: 0 1 auto; }
.activity-file-name { flex: 0 0 auto; max-width: 100%; color: var(--color-text); text-decoration: underline; text-underline-offset: 3px; }
.activity-file-action { flex: none; margin-left: auto; font-size: 12px; opacity: 0; transition: opacity .15s var(--ease-out); }
.activity-file-row:hover .activity-file-action, .activity-file-row:focus-visible .activity-file-action { opacity: 1; }
.activity-group-files { min-width: 0; padding-bottom: 4px; }
.activity-group-files > .activity-group-files-label { margin: 0 0 4px; color: var(--muted); font-size: 12px; line-height: 18px; }
.activity-group-files > .activity-file-row { min-height: 30px; padding-block: 4px; }
.activity-more-files { margin: 4px 0 0; }
.activity-more-files > summary { display: inline-flex; align-items: center; gap: 4px; min-height: 21px; padding: 0 8px; list-style: none; color: var(--muted); font-size: 12px; line-height: 21px; }
.activity-more-files > summary::-webkit-details-marker { display: none; }
.activity-more-files > summary:hover { color: var(--color-text); }
.activity-more-files > summary > svg { flex: none; width: 16px; height: 16px; }
.activity-more-files-body .activity-file-row { min-height: 30px; padding-block: 4px; }
.command-card { position: relative; }
.command-card .cmd { width: 100%; margin: 0; border: 0; border-radius: 0; background: none; text-align: left; }
.command-card .cmd[data-expanded="true"] { display: block; -webkit-line-clamp: unset; }
.command-card > .copy-status { position: absolute; z-index: 2; top: 4px; right: 8px; max-width: calc(100% - 24px); padding: 3px 6px; border-radius: 5px; background: var(--app-color-background-surface); box-shadow: var(--shadow-sm); font-size: 12px; }
@media (hover: none) {
.event-file-open, .activity-file-action { opacity: 1; } }

