payload.input:
const cmd=String.raw`@'
import fs from 'node:fs';
import postcss from 'postcss';
const oldConversation=fs.readFileSync('src/styles/conversation.css','utf8');
const oldPanels=fs.readFileSync('src/styles/panels.css','utf8');
const conversation=postcss.parse(oldConversation),panels=postcss.parse(oldPanels);
function move(container,dest) {
 for(const node of [...container.nodes]) {
  if(node.type==='rule') {
   const moved=node.selectors.filter(s=>/\.code-(block|toolbar)/.test(s)),kept=node.selectors.filter(s=>!/\.code-(block|toolbar)/.test(s));
   if(!moved.length)continue;
   dest.append(node.clone({selector:moved.join(', ')}));
   if(kept.length)node.selector=kept.join(', ');else node.remove();
  }else if(node.nodes){
   const clone=node.clone({nodes:[]});move(node,clone);
   if(clone.nodes.length)dest.append(clone);if(!node.nodes.length)node.remove();
  }
 }
}
panels.append(postcss.comment({text:'Markdown code blocks use the shared source surface.'}));move(conversation,panels);
console.log(JSON.stringify({conversation:{old:oldConversation,value:conversation.toString()},panels:{old:oldPanels,value:panels.toString()}}));
'@ | node --input-type=module`;
const result=await tools.exec_command({cmd,workdir:"D:\\Competition_this\\Agent\\desktop",max_output_tokens:45000});
if(result.exit_code!==0){text(result);exit();}
const data=JSON.parse(result.output);
let patch='*** Begin Patch\n';
for(const[name,file]of Object.entries(data)){
patch+='*** Update File: D:/Competition_this/Agent/desktop/src/styles/'+name+'.css\n@@\n'+file.old.trimEnd().split(/\r?\n/).map(l=>'-'+l).join('\n')+'\n'+file.value.trimEnd().split(/\r?\n/).map(l=>'+'+l).join('\n')+'\n';
}
patch+='*** End Patch';
text(await tools.apply_patch(patch));text(Object.fromEntries(Object.entries(data).map(([name,file])=>[name,file.value.length])));

