  await ingress.getByRole('button', { name: '接收此事件', exact: true }).click();
  await ingress.getByRole('status').filter({ hasText: '事件已接收' }).waitFor();
  await ingress.getByRole('button', { name: '接收此事件', exact: true }).click();
  await ingress.locator('.settings-result-record').getByRole('group').count();
  await page.waitForFunction(() => document.querySelector('.trigger-settings')?.textContent.includes('重复接收'));
  const ingressWrites = mutations.filter((entry) => entry.path === '/api/triggers');
  check(ingressWrites.length === 3 && ingressWrites.every((entry) => entry.payload.external_id === originalId), 'retry and repeat keep one durable event identity');
  check(ingressWrites[1].payload.payload.build === 7 && ingressWrites[1].payload.actor === 'alice' && ingressWrites[1].payload.addressed === true, 'structured ingress retains actor, addressing and JSON object fields');
  const light = await page.locator('.settings-content').evaluate((element) => getComputedStyle(element).backgroundColor);
  await page.locator('.settings-content').evaluate((element) => element.scrollTop = 0);
  await page.screenshot({ path: `${outputDir}/forge-triggers-light.png`, fullPage: true });
  await page.emulateMedia({ colorScheme: 'dark' });
  const dark = await page.locator('.settings-content').evaluate((element) => getComputedStyle(element).backgroundColor);
  check(light !== dark && dark === 'rgb(17, 17, 17)', 'trigger settings follow the system theme without a JS theme toggle');
  await page.setViewportSize({ width: 390, height: 844 });
  await page.screenshot({ path: `${outputDir}/forge-triggers-narrow-dark.png`, fullPage: true });
  check(await page.locator('.settings-content').evaluate((element) => element.scrollWidth <= element.clientWidth), '390px trigger settings have no horizontal content overflow');
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.emulateMedia({ colorScheme: 'light' });
  await nav.getByRole('button', { name: '模型库', exact: true }).click();
  const intelligence = page.locator('.model-intelligence');
  await intelligence.locator('.model-observations').waitFor();
  check(!mutations.some((entry) => entry.path === '/api/model-intelligence/benchmark'), 'opening model settings never starts a paid benchmark');
  const measurements = intelligence.locator('.model-measurement');
  check((await measurements.filter({ hasText: '请求传输成功率' }).innerText()).includes('75%') && (await measurements.filter({ hasText: '任务成功率' }).innerText()).includes('25%'), 'transport and task success rates remain separate with recorded sample counts');
  check((await measurements.filter({ hasText: '视觉' }).innerText()).includes('未知'), 'unsupported visual capability is never filled with a fake zero');
  await intelligence.getByRole('button', { name: '从供应商发现模型', exact: true }).click();
  await intelligence.getByText('已发现 1 个新模型，模型库已刷新。', { exact: true }).waitFor();
  await intelligence.getByLabel('观测模型', { exact: true }).locator('option[value="profile-discovered"]').waitFor({ state: 'attached' });
  check(mutations.find((entry) => entry.path === '/api/model-intelligence/discover').payload === null, 'model discovery sends the original body-free POST and refreshes the model list');
  await intelligence.getByLabel('观测模型', { exact: true }).selectOption('profile-disabled');
  await intelligence.locator('.model-observations').waitFor();
  check(await intelligence.getByRole('button', { name: '开始固定样例测量', exact: true }).isDisabled(), 'a disabled model cannot start a live probe');
  await intelligence.getByLabel('观测模型', { exact: true }).selectOption('profile-enabled');
  await intelligence.locator('.model-observations').waitFor();
  await intelligence.getByRole('button', { name: '开始固定样例测量', exact: true }).click();
  await intelligence.getByText('固定样例测量已记录。请查看各维度结果。', { exact: true }).waitFor();
  const probes = mutations.filter((entry) => entry.path === '/api/model-intelligence/benchmark');
  check(probes.length === 1 && probes[0].payload.profile_id === 'profile-enabled' && JSON.stringify(probes[0].payload.dimensions) === '["mathematics"]', 'only the explicit click starts one probe with the selected profile and exact dimensions');
  failSnapshot = true;
  await intelligence.getByRole('button', { name: '刷新模型观测', exact: true }).click();
  await intelligence.getByRole('alert').filter({ hasText: 'synthetic snapshot failure' }).waitFor();
  check(await intelligence.locator('.model-observations').count() === 0, 'a failed observation refresh clears the previous snapshot');
  failSnapshot = false;
  await intelligence.getByRole('button', { name: '刷新模型观测', exact: true }).click();
  await intelligence.locator('.model-observations').waitFor();
  await page.locator('.settings-content').evaluate((element) => element.scrollTop = 0);
  await page.screenshot({ path: `${outputDir}/forge-models-light.png`, fullPage: true });
  await page.emulateMedia({ colorScheme: 'dark' });
  await page.setViewportSize({ width: 390, height: 844 });
  await page.screenshot({ path: `${outputDir}/forge-models-narrow-dark.png`, fullPage: true });
  check(await page.locator('.settings-content').evaluate((element) => element.scrollWidth <= element.clientWidth), '390px model measurements and controls have no horizontal content overflow');
  check(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), '390px settings preserve the overall shell bounds');
  check(missing.length === 0, `all requested endpoints have synthetic fixtures: ${missing.join(', ')}`);
  return { status: 'passed', fixture: 'synthetic HTTP only, no Provider', checks, calls: [...new Set(calls)], mutations: mutations.map((entry) => entry.path), screenshots: ['forge-triggers-light.png', 'forge-triggers-narrow-dark.png', 'forge-models-light.png', 'forge-models-narrow-dark.png'] };
}

tools.description:
Run JavaScript code to orchestrate/compose tool calls
- Evaluates the provided JavaScript code in a fresh V8 isolate as an async module.
- All nested tools are available on the global `tools` object, for example `await tools.exec_command(...)`. Tool names are exposed as normalized JavaScript identifiers, for example `await tools.mcp__ologs__get_profile(...)`.
- Nested tool methods take either a string or an object as their input argument.
- Nested tools return either an object or a string, based on the description.
- Runs raw JavaScript -- no Node, no file system, no network access, no console.
- Accepts raw JavaScript source text, not JSON, quoted strings, or markdown code fences.
- You may optionally start the tool input with a first-line pragma like `// @exec: {"yield_time_ms": 10000, "max_output_tokens": 1000}`.
- `yield_time_ms` asks `exec` to yield early if the script is still running. Defaults to 30000 ms.
- `max_output_tokens` sets the token budget for direct `exec` results. Defaults to 10000 tokens.
- When the JS code is fully evaluated, the isolate's lifetime ends and unawaited promises are silently discarded.

- Global helpers:
- `exit()`: Immediately ends the current script successfully (like an early return from the top level).
- `text(value: string | number | boolean | undefined | null)`: Appends a text item. Non-string values are stringified with `JSON.stringify(...)` when possible.
- `image(imageUrlOrItem: string | { image_url: string } | ImageContent)`: Appends an image item. `image_url` should be a base64-encoded `data:` URL. To forward an MCP tool image, pass an individual `ImageContent` block from `result.content`, for example `image(result.content[0])`.
- `audio(audioUrlOrItem: string | { audio_url: string } | AudioContent)`: Appends an audio item. `audio_url` should be a base64-encoded `data:` URL. To forward an MCP tool audio block, pass an individual `AudioContent` block from `result.content`, for example `audio(result.content[0])`.
- `generatedImage(result: { image_url: string; output_hint?: string })`: Appends an image-generation result and its optional output hint. HTTP(S) URLs are not supported.
- `store(key: string, value: any)`: stores a serializable value under a string key for later `exec` calls in the same session.
- `load(key: string)`: returns the stored value for a string key, or `undefined` if it is missing.
- `notify(value: string | number | boolean | undefined | null)`: immediately injects an extra `custom_tool_call_output` for the current `exec` call. Values are stringified like `text(...)`.
- `setTimeout(callback: () => void, delayMs?: number)`: schedules a callback to run later and returns a timeout id. Pending timeouts do not keep `exec` alive by themselves; await an explicit promise if you need to wait for one.
- `clearTimeout(timeoutId?: number)`: cancels a timeout created by `setTimeout`.
- `ALL_TOOLS`: metadata for the enabled nested tools as `{ name, description }` entries.
- `yield_control()`: yields the accumulated output to the model immediately while the script keeps running.

Some deferred nested tools may be omitted from this description. They are still available on the global `tools` object and listed in `ALL_TOOLS`.
To find one, filter `ALL_TOOLS` by `name` and `description`.

Tool availability can change between calls.

Shared MCP Types:
```ts
type Role = "user" | "assistant";
type MetaObject = Record<string, unknown>;
type Annotations = {
  audience?: Role[];
  priority?: number;
  lastModified?: string;
};
type Icon = {
  src: string;
  mimeType?: string;
  sizes?: string[];
  theme?: "light" | "dark";
};
type TextResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  text: string;
};
type BlobResourceContents = {
  uri: string;
  mimeType?: string;
  _meta?: MetaObject;
  blob: string;
};
type TextContent = {
  type: "text";
  text: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ImageContent = {
  type: "image";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type AudioContent = {
  type: "audio";
  data: string;
  mimeType: string;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ResourceLink = {
  icons?: Icon[];
  name: string;
  title?: string;
  uri: string;
  description?: string;
  mimeType?: string;
  annotations?: Annotations;
  size?: number;
  _meta?: MetaObject;
  type: "resource_link";
};
type EmbeddedResource = {
  type: "resource";
  resource: TextResourceContents | BlobResourceContents;
  annotations?: Annotations;
  _meta?: MetaObject;
};
type ContentBlock =
  | TextContent
  | ImageContent
  | AudioContent
  | ResourceLink
  | EmbeddedResource;
type CallToolResult<TStructured = { [key: string]: unknown }> = {
  _meta?: MetaObject;
  content: ContentBlock[];
  isError?: boolean;
  structuredContent?: TStructured;
  [key: string]: unknown;
};
```

### `apply_patch`
The `apply_patch` tool can be used to edit files. This is a FREEFORM tool, so do not wrap the patch in JSON.

exec tool declaration:
```ts
declare const tools: { apply_patch(input: string): Promise<unknown>; };
```

### `create_goal`
Create a goal only when explicitly requested by the user or system/developer instructions; do not infer goals from ordinary tasks.
Set token_budget only when an explicit token budget is requested. Fails if an unfinished goal exists; use update_goal only for status.

exec tool declaration:
```ts
declare const tools: { create_goal(args: {
  // Required. The concrete objective to start pursuing. This starts a new active goal when no goal exists or replaces the current goal when it is complete.
  objective: string;
  // Positive token budget for the new goal. Omit unless explicitly requested.
  token_budget?: number;
}): Promise<unknown>; };
```

### `exec_command`
Runs a command in a PTY, returning output or a session ID for ongoing interaction.

Windows safety rules:
- Do not compose destructive filesystem commands across shells. Do not enumerate paths in PowerShell and then pass them to `cmd /c`, batch builtins, or another shell for deletion or moving. Use one shell end-to-end, prefer native PowerShell cmdlets such as `Remove-Item` / `Move-Item` with `-LiteralPath`, and avoid string-built shell commands for file operations.
- Before any recursive delete or move on Windows, verify the resolved absolute target paths stay within the intended workspace or explicitly named target directory. Never issue a recursive delete or move against a computed path if the final target has not been checked.
- When using `Start-Process` to launch a background helper or service, pass `-WindowStyle Hidden` unless the user explicitly asked for a visible interactive window. Use visible windows only for interactive tools the user needs to see or control.

exec tool declaration:
```ts
declare const tools: { exec_command(args: {
  // Shell command to execute.
  cmd: string;
  // User-facing approval question for `require_escalated`; omit otherwise.
  justification?: string;
  // True runs the shell with -l/-i semantics; false disables them. Defaults to true.
  login?: boolean;
  // Output token budget. Defaults to 10000 tokens; larger requests may be capped by policy.
  max_output_tokens?: number;
  // Reusable approval prefix for `cmd`, only with `sandbox_permissions: "require_escalated"`; for example ["git", "pull"].
  prefix_rule?: Array<string>;
  // Per-command sandbox override. Defaults to `use_default`; use `require_escalated` for unsandboxed execution.
  sandbox_permissions?: "use_default" | "require_escalated";
  // Shell binary to launch. Defaults to the user's default shell.
  shell?: string;
  // True allocates a PTY for the command; false or omitted uses plain pipes.
  tty?: boolean;
  // Working directory for the command. Defaults to the turn cwd.
  workdir?: string;
  // Maximum time to wait before returning a session ID for a still-running command. Commands that finish sooner return immediately. For ordinary commands, omit this parameter to use the 10000 ms default. Effective range on Windows is 10000-30000 ms.
  yield_time_ms?: number;
}): Promise<{
  // Chunk identifier included when the response reports one.
  chunk_id?: string;
  // Process exit code when the command finished during this call.
  exit_code?: number;
  // Approximate token count before output truncation.
  original_token_count?: number;
  // Command output text, possibly truncated.
  output: string;
  // Session identifier to pass to write_stdin when the process is still running.
  session_id?: number;
  // Elapsed wall time spent waiting for output in seconds.
  wall_time_seconds: number;
}>; };
```

