/* Messages, Markdown, tools, approvals and inline file results. */
.home-files-button { position: absolute; top: 14px; right: 20px; display: flex; align-items: center; gap: 6px; height: 28px; border: 0; border-radius: 7.5px; background: transparent; color: var(--muted); font-size: 12px; }
.home-files-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
